import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import { Link } from 'react-router-dom';
import { FiSearch, FiDollarSign, FiClock, FiUser, FiBookmark, FiCheckCircle, FiArrowRight } from 'react-icons/fi';
import ApplyModal from '../components/projects/ApplyModal';

const Browse = () => {
  const { user } = useContext(AuthContext);
  const [projects, setProjects] = useState([]);
  const [filteredProjects, setFilteredProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [budgetFilter, setBudgetFilter] = useState('');
  const [levelFilter, setLevelFilter] = useState('');
  const [appliedProjects, setAppliedProjects] = useState([]);
  const [selectedProject, setSelectedProject] = useState(null);
  const [showApplyModal, setShowApplyModal] = useState(false);
  const [animateIn, setAnimateIn] = useState(false);

  useEffect(() => {
    fetchProjects();
    if (user && user.userType === 'student') fetchAppliedProjects();
    setTimeout(() => setAnimateIn(true), 100);
  }, [user]);

  const fetchProjects = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/match/projects', {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
      setProjects(res.data);
      setFilteredProjects(res.data);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  const fetchAppliedProjects = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/application/student', {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
      setAppliedProjects(res.data.map(app => app.project._id));
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    let filtered = projects;
    if (searchTerm) filtered = filtered.filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()) || p.description.toLowerCase().includes(searchTerm.toLowerCase()));
    if (categoryFilter) filtered = filtered.filter(p => p.category === categoryFilter);
    if (budgetFilter === 'low') filtered = filtered.filter(p => p.budget < 500);
    else if (budgetFilter === 'medium') filtered = filtered.filter(p => p.budget >= 500 && p.budget <= 1500);
    else if (budgetFilter === 'high') filtered = filtered.filter(p => p.budget > 1500);
    if (levelFilter) filtered = filtered.filter(p => p.experienceLevel === levelFilter);
    setFilteredProjects(filtered);
  }, [searchTerm, categoryFilter, budgetFilter, levelFilter, projects]);

  const handleApply = (e, project) => {
    e.preventDefault();
    e.stopPropagation();
    setSelectedProject(project);
    setShowApplyModal(true);
  };

  const getMatchColor = (score) => {
    if (score >= 75) return 'bg-green-100 text-green-700 border-green-300';
    if (score >= 50) return 'bg-yellow-100 text-yellow-700 border-yellow-300';
    return 'bg-red-100 text-red-700 border-red-300';
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-green-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600 font-medium">Loading projects...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className={`max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 transition-all duration-700 ${animateIn ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
        
        {/* Header */}
        <div className="mb-8 animate-fade-in">
          <h1 className="text-4xl font-bold text-gray-800 mb-2">Browse Projects</h1>
          <p className="text-gray-600">Projects matched to your skills (if profile exists). Otherwise showing all projects.</p>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-8 animate-slide-up" style={{animationDelay: '0.1s'}}>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="relative group">
              <FiSearch className="absolute left-3 top-3 text-gray-400 group-focus-within:text-green-600 transition" size={18}/>
              <input type="text" placeholder="Search projects..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-green-500 focus:ring-2 focus:ring-green-100 transition" />
            </div>
            <select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)} className="px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-green-500 focus:ring-2 focus:ring-green-100 transition">
              <option value="">All Categories</option>
              <option value="Web Development">Web Development</option>
              <option value="Mobile App">Mobile App</option>
              <option value="Design">Design</option>
              <option value="Content Writing">Content Writing</option>
              <option value="Marketing">Marketing</option>
            </select>
            <select value={budgetFilter} onChange={(e) => setBudgetFilter(e.target.value)} className="px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-green-500 focus:ring-2 focus:ring-green-100 transition">
              <option value="">All Budgets</option>
              <option value="low">Low (&lt; $500)</option>
              <option value="medium">Medium ($500 - $1500)</option>
              <option value="high">High (&gt; $1500)</option>
            </select>
            <select value={levelFilter} onChange={(e) => setLevelFilter(e.target.value)} className="px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-green-500 focus:ring-2 focus:ring-green-100 transition">
              <option value="">All Levels</option>
              <option value="beginner">Beginner</option>
              <option value="intermediate">Intermediate</option>
              <option value="expert">Expert</option>
            </select>
          </div>
        </div>

        {/* Project Count */}
        <div className="mb-4 animate-fade-in" style={{animationDelay: '0.2s'}}>
          <p className="text-gray-600">Showing <span className="font-bold text-gray-800">{filteredProjects.length}</span> project{filteredProjects.length !== 1 ? 's' : ''}</p>
        </div>

        {/* Projects Grid */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProjects.map((project, index) => {
            const hasApplied = appliedProjects.includes(project._id);
            return (
              <Link key={project._id} to={`/project/${project._id}`} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-xl hover:border-green-200 transition-all duration-300 transform hover:-translate-y-1 animate-slide-up group block" style={{animationDelay: `${0.1 * (index % 6)}s`}}>
                
                {/* Match Badge */}
                {project.matchScore !== undefined && (
                  <div className="absolute top-4 right-4 z-10">
                    <div className={`px-3 py-1 rounded-full border font-bold text-sm ${getMatchColor(project.matchScore)} shadow-sm animate-pulse-gentle`}>
                      {project.matchScore}% Match
                    </div>
                  </div>
                )}

                <div className="p-6 relative">
                  
                  {/* Applied Badge */}
                  {hasApplied && (
                    <div className="absolute top-2 left-2">
                      <div className="flex items-center space-x-1 px-3 py-1 bg-blue-50 text-blue-700 rounded-full border border-blue-200 text-xs font-medium animate-bounce-in">
                        <FiCheckCircle size={12}/><span>Applied</span>
                      </div>
                    </div>
                  )}

                  {/* Bookmark Icon */}
                  <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); }} className="absolute top-2 right-2 p-2 text-gray-400 hover:text-green-600 transition-all duration-300 hover:scale-110 hover:rotate-12">
                    <FiBookmark size={18}/>
                  </button>

                  <div className="mt-8">
                    <h3 className="text-xl font-bold text-gray-800 mb-2 group-hover:text-green-600 transition-colors duration-300">{project.title}</h3>
                    <p className="text-gray-600 text-sm mb-4 line-clamp-2">{project.description}</p>

                    {/* Skills */}
                    <div className="flex flex-wrap gap-2 mb-4">
                      {project.requiredSkills.slice(0, 4).map((skill, i) => (
                        <span key={i} className="px-3 py-1 bg-gray-100 text-gray-700 rounded-full text-xs font-medium hover:bg-green-100 hover:text-green-700 transition-all duration-200 cursor-default">{skill}</span>
                      ))}
                      {project.requiredSkills.length > 4 && <span className="px-3 py-1 bg-gray-100 text-gray-500 rounded-full text-xs">+{project.requiredSkills.length - 4}</span>}
                    </div>

                    {/* Meta Info */}
                    <div className="flex items-center justify-between text-sm text-gray-500 mb-4">
                      <div className="flex items-center space-x-1 hover:text-green-600 transition-colors"><FiDollarSign size={14}/><span className="font-semibold">${project.budget}</span></div>
                      <div className="flex items-center space-x-1 hover:text-green-600 transition-colors"><FiClock size={14}/><span>{project.duration}</span></div>
                      <div className="px-2 py-1 bg-green-50 text-green-700 rounded text-xs font-medium capitalize">{project.experienceLevel}</div>
                    </div>

                    {/* Posted By */}
                    <div className="flex items-center space-x-2 text-xs text-gray-500 mb-4 pb-4 border-b border-gray-100">
                      <FiUser size={12}/><span>Posted by: <span className="font-medium text-gray-700">{project.client?.name || 'Client'}</span></span>
                    </div>

                    {/* View Details Button */}
                    <div className="flex items-center justify-between">
                      <span className="text-green-600 font-semibold text-sm group-hover:gap-2 flex items-center gap-1 transition-all">
                        View Details <FiArrowRight className="group-hover:translate-x-1 transition-transform"/>
                      </span>
                      
                      {user && user.userType === 'student' && (
                        <button onClick={(e) => handleApply(e, project)} disabled={hasApplied} className={`px-4 py-2 rounded-lg font-semibold text-sm transition-all duration-300 transform ${hasApplied ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-green-600 text-white hover:bg-green-700 hover:shadow-lg active:scale-95'}`}>
                          {hasApplied ? 'Applied' : 'Quick Apply'}
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>

        {filteredProjects.length === 0 && (
          <div className="text-center py-20 animate-fade-in">
            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <FiSearch className="text-gray-400" size={32}/>
            </div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">No projects found</h3>
            <p className="text-gray-600">Try adjusting your filters or search terms.</p>
          </div>
        )}
      </div>

      {showApplyModal && <ApplyModal project={selectedProject} onClose={() => setShowApplyModal(false)} onSuccess={fetchAppliedProjects} />}
    </div>
  );
};

export default Browse;
